/** Write the message into `inputs_fields`, returning the serialized JSON. */
export function setScheduleMessage(
    inputsText: string,
    message: string,
    isChat: boolean,
    primaryKey: string,
): string {
    const obj = parseObject(inputsText)
    const trimmed = message.trim()
    // Mirrors the getter's shape check so an edit writes back where it was read from.
    if (isChat || isMessagesPayload(obj)) {
        if (trimmed) obj.messages = [{role: "user", content: message}]
        else delete obj.messages
    } else if (trimmed) {
        obj[primaryKey] = message
    } else {
        delete obj[primaryKey]
    }
    return Object.keys(obj).length ? JSON.stringify(obj, null, 2) : "{}"
}

/**
 * Rewrite the message into a new agent shape after the bound agent resolves.
 *
 * The drawers derive `isChat`/`primaryKey` from an async query, so a message typed before the
 * agent is known is stored under the wrong key. Re-reading it under the new shape yields "" —
 * the composer looks empty while `inputs_fields` still holds the old shape, which then saves
 * against an agent that can't receive it.
 *
 * `setScheduleMessage` alone can't do this: it preserves sibling keys, so writing under the new
 * shape would leave `{"message": "…", "messages": [...]}`. The old shape's key must go first.
 * A mapping the composer can't read is returned untouched — there's nothing safe to migrate.
 */
export function remapMessageShape(
    inputsText: string,
    prev: {isChat: boolean; primaryKey: string},
    next: {isChat: boolean; primaryKey: string},
): string {
    const message = getScheduleMessage(inputsText, prev.isChat, prev.primaryKey)
    if (!message) return inputsText
    const obj = parseObject(inputsText)
    if (prev.isChat || isMessagesPayload(obj)) delete obj.messages
    else delete obj[prev.primaryKey]
    return setScheduleMessage(JSON.stringify(obj), message, next.isChat, next.primaryKey)
}

/**
 * Best-effort message preview from a resolved `inputs_fields` object — for list rows
 * where the agent schema isn't handy. Reads the first chat user message, else the first
 * non-empty string value. Empty string when there's nothing to show.
 */
export function getScheduleMessagePreview(inputsFields: unknown): string {
    // Same two checks the workflow molecule makes, against the revision we just resolved: the
    // flag first, then a `messages` property on the input schema for when the flag lags behind.
    const inputSchema = revision?.data?.schemas?.inputs as Record<string, unknown> | undefined
    const isChat = useMemo(() => {
        if (revision?.flags?.is_chat) return true
        const properties = inputSchema?.properties as Record<string, unknown> | undefined
        return Boolean(properties?.messages)
    }, [inputSchema, revision?.flags?.is_chat])

    const primaryKey = useMemo(() => {
        if (isChat) return "messages"
        const ports = extractInputPortsFromSchema(inputSchema ?? null)
        return ports.find((port) => port.type === "string")?.key ?? "message"
    }, [inputSchema, isChat])

    // The field is never locked. Before an agent is picked — or before its revision lands — the
    // message is typed under the completion key, and the migration below rewrites it into the
    // agent's real shape the moment that shape is known. A locked field was the earlier answer,
    // and it read as broken: nothing on the screen said WHY it would not take input.
    const resolving = Boolean(agentId) && !revision && latest.isPending

    // The revision can land after a message was typed, or an automation can have been saved under
    // the wrong key before this resolved at all. Either way the stored shape is migrated to the
    // one the agent takes, deleting the old key rather than leaving both.
    const shape = useMemo(() => ({isChat, primaryKey}), [isChat, primaryKey])
    const previousShape = useRef(shape)
    useEffect(() => {
        const previous = previousShape.current
        previousShape.current = shape
        if (resolving) return
        if (previous.isChat === shape.isChat && previous.primaryKey === shape.primaryKey) return
        const next = remapMessageShape(inputsText, previous, shape)
        if (next === inputsText) return
        try {
            onCommit(JSON.parse(next) as Record<string, unknown>)
        } catch {
            // A mapping the composer cannot read is left exactly as it was.
        }
    }, [inputsText, onCommit, resolving, shape])

    const onChange = useCallback(
        (next: string) => {
            try {
                const parsed: unknown = JSON.parse(next)
                if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return
                onCommit(parsed as Record<string, unknown>)
            } catch {
                // The composer only ever writes valid JSON; an unparseable value is not ours.
            }
        },
        [onCommit],
    )

    return (
        <AutomationField label="Instruction">
            <MessageComposer
                inputsText={inputsText}
                onChange={onChange}
                isChat={isChat}
                primaryKey={primaryKey}
            />
        </AutomationField>
    )
}

